<?php
namespace Nakhostin\PerformanceEngine\Optimization;
final class OptimizationManifest { private const VERSION = 1; private $data; public function __construct( array $data ) { $data['manifest_version'] = self::VERSION; $this->data = $data; } public static function from_array( array $data ): ?self { return self::VERSION === (int) ( $data['manifest_version'] ?? 0 ) && ! empty( $data['page_signature'] ) && ! empty( $data['generated_at'] ) ? new self( $data ) : null; } public function to_array(): array { return $this->data; } public function section( string $name ): array { return is_array( $this->data[ $name ] ?? null ) ? $this->data[ $name ] : array(); } public function source_url(): string { return (string) ( $this->data['source_url'] ?? '' ); } public function is_stale( ?int $now = null, int $ttl = 604800 ): bool { return ( $now ?? time() ) - (int) $this->data['generated_at'] > $ttl; } }
